const thunderRunnerSheet=new Image();thunderRunnerSheet.assetSrc='assets/thunder-runner-v1.png';
function beginThunderRunner(e){let dx=p.x-e.x,dy=p.y-e.y,len=Math.hypot(dx,dy),ux=dx/(len||1),uy=dy/(len||1);if(!len)ux=1;let reach=Math.max(160,Math.min(280,len)),origin={x:e.x,y:e.y},points=[{x:e.x+ux*reach-uy*90,y:e.y+uy*reach+ux*90},{x:e.x+ux*reach+uy*90,y:e.y+uy*reach-ux*90},{x:e.x+ux*(reach+100),y:e.y+uy*(reach+100)}],legs=[],from=origin;for(let target of points){let dx=target.x-from.x,dy=target.y-from.y,d=Math.hypot(dx,dy),end={...from},blocked=false;for(let s=6;s<d+6;s+=6){let r=Math.min(s,d),q={x:from.x+dx/(d||1)*r,y:from.y+dy/(d||1)*r};if(!passable(q.x,q.y,18)||!lineClear(end,q,18)){blocked=true;break;}end=q;}legs.push({start:{...from},end,blocked,done:false,hit:false});from=end;if(blocked)break;}e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'thunderZigzag',bespoke:true,windup:.9,origin,last:{...origin},legs,crashed:false,crashAt:null};e.facing=dx-dy<0?-1:1;}
function thunderRunnerContact(point,start,end){let dx=end.x-start.x,dy=end.y-start.y,d2=dx*dx+dy*dy;if(d2<1e-10)return false;let t=Math.max(0,Math.min(1,((point.x-start.x)*dx+(point.y-start.y)*dy)/d2));return Math.hypot(point.x-start.x-dx*t,point.y-start.y-dy*t)<=28+1e-8;}
const thunderRunnerAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r6e5')return thunderRunnerAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='thunderZigzag'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=340&&clear){beginThunderRunner(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,138*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 for(let [i,leg]of a.legs.entries()){let startTime=Math.round((.9+i*.6)*1e6)/1e6;if(a.crashed||leg.done||e.elapsed<startTime)continue;let t=e.elapsed>=startTime+.25-1e-8?1:Math.max(0,(e.elapsed-startTime)/.25),q={x:leg.start.x+(leg.end.x-leg.start.x)*t,y:leg.start.y+(leg.end.y-leg.start.y)*t},from={x:e.x,y:e.y},dx=q.x-e.x,dy=q.y-e.y,n=Math.max(1,Math.ceil(Math.hypot(dx,dy)/6));for(let j=0;j<n;j++){let x=e.x+dx/n,y=e.y+dy/n;if(!passable(x,y,18)||!lineClear(e,{x,y},18)){a.crashed=true;a.crashAt=e.elapsed;break;}e.x=x;e.y=y;}a.last={x:e.x,y:e.y};if(Math.hypot(dx,dy)>.01)e.facing=dx-dy<0?-1:1;if(!leg.hit&&thunderRunnerContact(p,from,a.last)&&lineClear(e,p)){leg.hit=true;e.struck=true;hurt(58);}if(t===1){leg.done=true;playSound('impact',e.x,e.y);if(leg.blocked){a.crashed=true;a.crashAt=e.elapsed;}}}
 if(a.crashed?e.elapsed>=a.crashAt+1.2:e.elapsed>=3.1){e.attack=null;e.state='idle';e.t=2.4;}
};
const thunderRunnerDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r6e5'||!thunderRunnerSheet.complete||!thunderRunnerSheet.naturalWidth||!thunderRunnerSheet.naturalHeight)return thunderRunnerDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='thunderZigzag'){let moving=e.attack.legs.some((leg,i)=>!leg.done&&e.elapsed>=.9+i*.6&&e.elapsed<1.15+i*.6);f={row:2,col:e.attack.crashed||e.elapsed>=2.35?3:e.elapsed<.9?0:moving?1:2};}let q=project(e.x,e.y),sw=thunderRunnerSheet.naturalWidth/4,sh=thunderRunnerSheet.naturalHeight/3,w=250,h=w*sh/sw,anchor=[.89,.85,.8][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,thunderRunnerSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(thunderRunnerSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const thunderRunnerSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r6e5'?155:thunderRunnerSizeBase(e);
const thunderRunnerGroundBase=drawGroundEffects;drawGroundEffects=()=>{thunderRunnerGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e5'):enemies)){let a=e.attack;if(e.species!=='r6e5'||e.hp<=0||a?.pattern!=='thunderZigzag'||a.crashed)continue;for(let [i,leg]of a.legs.entries()){if(leg.done||!visibleAt(leg.start.x,leg.start.y)&&!visibleAt(leg.end.x,leg.end.y))continue;let dx=leg.end.x-leg.start.x,dy=leg.end.y-leg.start.y,len=Math.hypot(dx,dy);if(len<.01)continue;let nx=-dy/len*28,ny=dx/len*28,active=e.elapsed>=.9+i*.6,points=[{x:leg.start.x+nx,y:leg.start.y+ny},{x:leg.end.x+nx,y:leg.end.y+ny},{x:leg.end.x-nx,y:leg.end.y-ny},{x:leg.start.x-nx,y:leg.start.y-ny}];ctx.save();ctx.fillStyle=active?'#edc48344':'#aa8dd51b';ctx.strokeStyle=active?'#ffe2a5':'#b8a2d5';ctx.lineWidth=active?3:1;ctx.beginPath();points.forEach((p,j)=>{let q=project(p.x,p.y);if(j)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();groundRing(leg.start.x,leg.start.y,28,'#b8a2d5',1);groundRing(leg.end.x,leg.end.y,28,'#b8a2d5',1);}}};
